mapper.insert:
INSERT INTO model_provider (
tenant_id, type, name, description, api_key, base_url, status, is_public, creator, active, create_time, update_time
) VALUES (
#{tenantId}, #{type}, #{name}, #{description}, #{apiKey}, #{baseUrl}, #{status}, #{isPublic}, #{creator}, #{active}, #{createTime},
#{updateTime}
)

mapper.select:
SELECT * FROM model_provider
WHERE active = 1
AND (tenant_id = #{tenantId} OR is_public = 1)

    AND (name LIKE CONCAT('%', #{name}, '%') OR description LIKE CONCAT('%', #{name}, '%'))


    AND type = #{type}


    AND status = #{status}


    AND is_public = #{isPublic}

ORDER BY status DESC, update_time DESC
